1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/dmi_poll.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	#include "hybrid/v_regfile_xfer.hpp"
12	
13	#include <algorithm>
14	#include <array>
15	#include <cstdint>
16	#include <span>
17	
18	namespace hybrid
19	{
20	
21	class StateDrain
22	{
23	public:
24	  using RD = ResumeDriver;
25	
26	  explicit StateDrain(DmiBus& bus)
27	      : bus_{bus}
28	  {}
29	
30	  // F16: stash the warmup-window snapshot (mcycle, minstret captured K
31	  // retires after vsim entry). Both drain() and drain_with_passthrough()
32	  // copy these into the returned state. Zero when MeasureStartSnapshot
33	  // never fired (K=0 or workload exited inside the warmup window).
34	  void set_warmup_snapshot(uint64_t mcycle, uint64_t minstret)
35	  {
36	    warmup_mcycle_   = mcycle;
37	    warmup_minstret_ = minstret;
38	  }
39	
40	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
41	  // drain_with_passthrough when the QEMU 1 snapshot is available.
42	  auto drain() -> hybrid_state_v1
43	  {
44	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
45	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
46	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
47	                   "StateDrain halt");
48	
49	    hybrid_state_v1 state{};
50	    state.magic   = HYBRID_STATE_MAGIC;
51	    state.version = HYBRID_STATE_VERSION;
52	    state.flags   = HYBRID_FLAG_RV64;
53	    // L6: dcsr.prv holds the privilege the hart was in when the halt landed.
54	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
55	                                  "StateDrain DCSR") & 0x3u;
56	
57	    for (uint16_t i = 1; i < 32; ++i)
58	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
59	
60	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
61	    state.mcycle_at_measure_start   = warmup_mcycle_;
62	    state.minstret_at_measure_start = warmup_minstret_;
63	    return state;
64	  }
65	
66	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
67	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
68	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
69	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
70	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
71	  // and vreg remain pass-through (read-only / too large for DM).
72	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
73	  // contribution would otherwise be discarded as the passthrough preserves
74	  // QEMU1's pre-handoff value.
75	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
76	  {
77	    auto state       = input;
78	    const auto fresh = drain();
79	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
80	              std::begin(state.gpr) + 1);
81	    state.pc   = fresh.pc;
82	    state.priv = fresh.priv;  // L6: privilege at the exit halt, not QEMU1's
83	
84	    if (input.flags & HYBRID_FLAG_FP) {
85	      for (uint16_t i = 0; i < 32; ++i)
86	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
87	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
88	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
89	    }
90	
91	    if (input.flags & HYBRID_FLAG_V) {
92	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
93	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
94	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
95	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
96	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
97	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
98	    }
99	
100	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
101	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
102	
103	    // V data regfile: dump v0..v31 to the shared scratch region via the
104	    // Program Buffer LAST -- after every architectural read above -- so the
105	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
106	    // cannot corrupt the values already captured. The simulator's
107	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
108	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
109	    if (input.flags & HYBRID_FLAG_V)
110	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, input.vlenb,
111	                      /*load=*/false);
112	
113	    state.mcycle_at_measure_start   = warmup_mcycle_;
114	    state.minstret_at_measure_start = warmup_minstret_;
115	    return state;
116	  }
117	
118	  // cosim_roi F1: checkpoint drain. Same capture as drain_with_passthrough,
119	  // but the hart must keep running afterwards. The exit drain may clobber
120	  // freely (the run ends there); a checkpoint must undo the dump sweep's
121	  // clobbers -- vtype/vl/vstart and the x5/x6/x7 scratch -- from the freshly
122	  // drained values, then resume. DPC is untouched, so the hart continues
123	  // exactly where the halt landed.
124	  auto drain_checkpoint(const hybrid_state_v1& input) -> hybrid_state_v1
125	  {
126	    const auto state = drain_with_passthrough(input);
127	
128	    if (input.flags & HYBRID_FLAG_V) {
129	      // vtype+vl atomically via vsetvl (direct vtype write sets vill; vl is
130	      // read-only), staged in x5/x6 like the ResumeDriver Tier-B restore.
131	      write_register_abstract(bus_, regno_gpr(5), state.vl);
132	      write_register_abstract(bus_, regno_gpr(6), state.vtype);
133	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
134	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
135	      // vstart AFTER vsetvl (vsetvl zeroes it), via PB csrrw staged in x7 --
136	      // still scratch until the GPR rewrite below.
137	      write_register_abstract(bus_, regno_gpr(7), state.vstart);
138	      const std::array<uint32_t, 1> pb_vstart = {
139	        encode_csrrw(0, RD::kCsrVstart, 7) };
140	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vstart});
141	      // Scratch GPRs back to the drained architectural values.
142	      write_register_abstract(bus_, regno_gpr(5), state.gpr[5]);
143	      write_register_abstract(bus_, regno_gpr(6), state.gpr[6]);
144	      write_register_abstract(bus_, regno_gpr(7), state.gpr[7]);
145	    }
146	
147	    bus_.write(RD::kDmcontrol,
148	               RD::kDmcontrolDmactive | RD::kDmcontrolResumereq);
149	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllresumeack,
150	                   "StateDrain checkpoint resume");
151	    return state;
152	  }
153	
154	private:
155	  DmiBus& bus_;
156	  uint64_t warmup_mcycle_   = 0;  // F16: zero when warmup boundary never fired
157	  uint64_t warmup_minstret_ = 0;
