10	#include <cstdint>
11	#include <stdexcept>
12	#include <string>
13	
14	namespace hybrid {
15	
16	struct DmiBus
17	{
18	  virtual ~DmiBus() = default;
19	  virtual void write(uint8_t reg, uint32_t value) = 0;
20	  virtual auto read(uint8_t reg) -> uint32_t = 0;
21	};
22	
23	inline auto read_register_64(DmiBus& bus, uint16_t regno,
24	                             const char* poll_label) -> uint64_t;
25	
26	class ResumeDriver
27	{
28	public:
29	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
30	  // dmcontrol/dmstatus are run-control registers specific to this driver.
31	  static constexpr uint8_t kData0      = kDmiData0;
32	  static constexpr uint8_t kData1      = kDmiData1;
33	  static constexpr uint8_t kDmcontrol  = 0x10;
34	  static constexpr uint8_t kDmstatus   = 0x11;
35	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
36	  static constexpr uint8_t kCommand    = kDmiCommand;
37	
38	  static constexpr uint16_t kCsrDpc      = 0x7B1;
39	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
40	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
41	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
42	  static constexpr uint16_t kCsrFcsr     = 0x003;
43	  static constexpr uint16_t kCsrMstatus  = 0x300;
44	  static constexpr uint16_t kCsrMtvec    = 0x305;
45	  static constexpr uint16_t kCsrMcycle   = 0xB00;
46	  static constexpr uint16_t kCsrMinstret = 0xB02;
47	  static constexpr uint16_t kCsrVstart   = 0x008;
48	  static constexpr uint16_t kCsrVxsat    = 0x009;
49	  static constexpr uint16_t kCsrVxrm     = 0x00A;
50	  static constexpr uint16_t kCsrVcsr     = 0x00F;
51	  static constexpr uint16_t kCsrVtype    = 0xC21;
52	  static constexpr uint16_t kCsrVl       = 0xC20;
53	
54	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
55	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
56	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
57	
58	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
59	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
60	
61	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
62	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
63	
64	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
65	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
66	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
67	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
68	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
69	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
70	
71	  static constexpr unsigned kPollIterations = kDmiPollIterations;
72	
73	  explicit ResumeDriver(DmiBus& bus)
74	      : bus_{bus}
75	  {}
76	
77	  void resume(const hybrid_state_v1& state)
78	  {
79	    if (state.magic != HYBRID_STATE_MAGIC)
80	      throw std::runtime_error("ResumeDriver::resume: bad magic");
81	    if (state.version != HYBRID_STATE_VERSION)
82	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
83	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
84	    if (state.priv == 2 || state.priv > 3)
85	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
86	
87	    // dmactive must transition 0->1 in its own write before any other
88	    // DMCONTROL bit is honored (RISC-V Debug Spec).
89	    bus_.write(kDmcontrol, kDmcontrolDmactive);
90	    request_halt();
91	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
92	
93	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
94	    // accepted (FS or VS == Off disables the extension and the hart NACKs
95	    // the writes). The drained state.mstatus may legitimately carry FS or
96	    // VS at Off (e.g. an OS context-switched the regs away before the
97	    // trigger fired) -- gating the write on the drained field skips the
98	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
99	    // write mstatus when either extension is in scope; force-OR Initial
100	    // when the drained field is Off. This enable is local to the vsim
101	    // phase; the state.mstatus written to the handoff file is left
102	    // unmodified.
103	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
104	      uint64_t enable_mstatus = state.mstatus;
105	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
106	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
107	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
108	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
109	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
110	    }
111	
112	    // FPR restore (requires mstatus.FS enabled above).
113	    if (state.flags & HYBRID_FLAG_FP) {
114	      for (uint16_t i = 0; i < 32; ++i)
115	        write_64bit_register(regno_fpr(i), state.fpr[i]);
116	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
117	      // fallback scratch x5 is overwritten by the GPR loop below.
118	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
119	    }
120	
121	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
122	    // the GPR loop overwrites x5 afterward so state is preserved).
123	    if (state.flags & HYBRID_FLAG_V) {
124	      // V data regfile: reload v0..v31 from the shared scratch region via the
125	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
126	      // because the sweep's own vsetvl (e8/m1) clobbers vtype/vl/vstart, which
127	      // the restore then overwrites with the architectural values. The sweep
128	      // uses x5/x6/x7 as scratch (x7 is the base pointer); the GPR loop below
129	      // restores all three. The wire format reserves HYBRID_VLEN_BYTES_MAX per
130	      // register, so that -- not the runtime vlenb -- is the scratch stride.
131	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, state.vlenb,
132	                      /*load=*/true);
133	
134	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
135	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
136	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
137	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
138	      write_64bit_register(regno_gpr(5), state.vl);
139	      write_64bit_register(regno_gpr(6), state.vtype);
140	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
141	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
142	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
143	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
144	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
145	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
146	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
147	    }
148	
149	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
150	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
151	    // in the drained privilege; M-mode states skip the write (prv already 3).
152	    // Before the GPR loop: a PB fallback would clobber scratch x5.
153	    if (state.priv != 3) {
154	      // L2 slice: with PMP implemented and no matching entry, every S/U
155	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
156	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
157	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
158	      // RV64. Tolerant writes: entries beyond what the hart implements
159	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
160	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
161	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
162	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
163	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
164	
165	      const uint64_t dcsr =
166	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
167	      write_csr_abstract_or_pb(kCsrDcsr,
168	                               (dcsr & ~uint64_t{0x3}) | state.priv);
169	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
170	      // silently measure the ROI in the wrong privilege. Verify and abort.
171	      const uint64_t got =
172	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
173	        & 0x3u;
174	      if (got != state.priv)
175	        throw std::runtime_error(
176	          "ResumeDriver::resume: engine does not implement privilege level "
177	          + std::to_string(state.priv)
178	          + " (dcsr.prv pinned to " + std::to_string(got)
179	          + "); pick an S/U-capable engine");
180	    }
181	
182	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite).
183	    for (uint16_t i = 1; i < 32; ++i)
184	      write_64bit_register(regno_gpr(i), state.gpr[i]);
185	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
186	
187	    write_csr_tolerant(kCsrMtvec, state.mtvec);
188	
189	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
190	    // from QEMU1's drain value. Without this, vsim's local counter starts
191	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
192	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
193	    // overwrite here as the GPR loop already ran.
194	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
195	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
196	
197	    clear_cmderr_if_set();
198	    request_resume();
199	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
200	                   "ResumeDriver resume");
201	  }
202	
203	private:
204	  void request_halt()
205	  {
206	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
207	  }
208	
209	  void request_resume()
210	  {
211	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
212	  }
213	
214	  void write_64bit_register(uint16_t regno, uint64_t value)
215	  {
216	    write_register_abstract(bus_, regno, value);
217	  }
218	
219	  // Abstract-first CSR write with Program Buffer fallback.
220	  // Tries an abstract register write; if the DM signals cmderr, clears it,
221	  // stages the value in scratch_gpr via abstract GPR write, then executes a
222	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
223	  // to x5 (t0) which the GPR restore loop overwrites later.
224	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
225	                                 uint8_t scratch_gpr = 5)
226	  {
227	    write_64bit_register(regno_csr(csr), value);
228	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
229	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
230	    write_64bit_register(regno_gpr(scratch_gpr), value);
231	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
232	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
233	  }
234	
235	  // Write a CSR-addressable register and clear any cmderr the DM raised.
236	  // Used for CSRs whose abstract-access support may be implementation
237	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
238	  // remaining writes.
239	  void write_csr_tolerant(uint16_t csr, uint64_t value)
240	  {
241	    write_64bit_register(regno_csr(csr), value);
242	    clear_cmderr_if_set();
243	  }
244	
245	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
246	  // is rejected until the bits are W1C-cleared. We tolerate per-register
247	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
248	  // error before resuming so the hart isn't left in a stuck state.
249	  // B17: record the last observed non-zero cmderr and a clear count so a
250	  // partially-broken restore is observable via the public accessors
251	  // instead of silently swallowed.
252	  void clear_cmderr_if_set()
253	  {
254	    const auto status = bus_.read(kAbstractcs);
255	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
256	    if (code != 0u) {
257	      last_observed_cmderr_ = code;
258	      ++cmderr_clear_count_;
259	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
260	    }
261	  }
262	
263	  DmiBus& bus_;
264	  uint32_t last_observed_cmderr_ = 0;
265	  uint64_t cmderr_clear_count_   = 0;
266	
267	public:
268	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
269	  // at least one abstract write tripped a sticky cmderr the restore
270	  // tolerated by clearing. cmderr_clear_count() is the total number of
271	  // such clears across all calls into clear_cmderr_if_set() this run.
272	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
273	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
274	};
275	
276	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
277	// via an Abstract Command. Halts-and-reads contract: caller must have the
278	// hart in the halted state. Shared by StateDrain (drain at exit), and by
279	// MeasureStartSnapshot (snapshot at K-th retire). If abstractcs.cmderr
280	// goes sticky after the command, the helper clears it and reports 0
281	// rather than blocking the caller -- a missing CSR mirrors as zero
282	// instead of corrupting the adjacent field.
283	inline auto read_register_64(DmiBus& bus, uint16_t regno,
284	                             const char* poll_label = "read_register_64")
285	  -> uint64_t
286	{
287	  using RD = ResumeDriver;
288	  bus.write(RD::kCommand,
289	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
290	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
291	  const auto status = bus.read(RD::kAbstractcs);
292	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
293	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
294	    return 0u;
295	  }
296	  const uint64_t lo = bus.read(RD::kData0);
297	  const uint64_t hi = bus.read(RD::kData1);
298	  return lo | (hi << 32);
299	}
300	
301	}  // namespace hybrid
