323	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: V CSR reads issued after GPR reads")
324	{
325	  RecordingBus bus;
326	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
327	
328	  hybrid_state_v1 input{};
329	  input.magic   = HYBRID_STATE_MAGIC;
330	  input.version = HYBRID_STATE_VERSION;
331	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
332	  input.priv    = 3;
333	
334	  hybrid::StateDrain drain(bus);
335	  (void) drain.drain_with_passthrough(input);
336	
337	  // Find the last GPR COMMAND read and the first V CSR COMMAND read.
338	  std::optional<std::size_t> last_gpr_cmd;
339	  std::optional<std::size_t> first_vcsr_cmd;
340	  const std::initializer_list<uint16_t> vcsr_regnos = {
341	    hybrid::regno_csr(RD::kCsrVstart),
342	    hybrid::regno_csr(RD::kCsrVxsat),
343	    hybrid::regno_csr(RD::kCsrVxrm),
344	    hybrid::regno_csr(RD::kCsrVcsr),
345	    hybrid::regno_csr(RD::kCsrVtype),
346	    hybrid::regno_csr(RD::kCsrVl),
347	  };
348	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
349	    const auto& op = bus.ops[i];
350	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
351	    const uint16_t regno = op.value & 0xFFFFu;
352	    // Only register READS matter here. The V-data dump sweep also issues GPR
353	    // WRITES (x5/x6/x7 scratch) at the end of drain; those are not the
354	    // architectural GPR reads this ordering check is about.
355	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
356	    if (is_read && regno >= hybrid::regno_gpr(1) && regno <= hybrid::regno_gpr(31))
357	      last_gpr_cmd = i;
358	    for (uint16_t vcsr : vcsr_regnos)
359	      if (is_read && !first_vcsr_cmd && regno == vcsr)
360	        first_vcsr_cmd = i;
361	  }
362	  REQUIRE(last_gpr_cmd.has_value());
363	  REQUIRE(first_vcsr_cmd.has_value());
364	  CHECK(*last_gpr_cmd < *first_vcsr_cmd);
365	}
