397	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: PB dumps v0..v31 to scratch "
398	          "after the architectural counter/CSR reads")
399	{
400	  RecordingBus bus;
401	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
402	
403	  hybrid_state_v1 input{};
404	  input.magic   = HYBRID_STATE_MAGIC;
405	  input.version = HYBRID_STATE_VERSION;
406	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
407	  input.priv    = 3;
408	  input.vlenb   = 64;
409	
410	  hybrid::StateDrain drain(bus);
411	  (void) drain.drain_with_passthrough(input);
412	
413	  // (a) every v0..v31 is dumped via a vse8.v executed in the Program Buffer.
414	  std::vector<int> missing;
415	  std::optional<std::size_t> first_vse_idx;
416	  for (uint16_t v = 0; v < 32; ++v) {
417	    const uint32_t want = hybrid::encode_vse8_v(static_cast<uint8_t>(v), 7);
418	    std::optional<std::size_t> at;
419	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
420	      const auto& op = bus.ops[i];
421	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
422	          && op.value == want) { at = i; break; }
423	    }
424	    if (!at) { missing.push_back(v); continue; }
425	    if (!first_vse_idx || *at < *first_vse_idx) first_vse_idx = at;
426	  }
427	  CHECK(missing.empty());
428	  REQUIRE(first_vse_idx.has_value());
429	
430	  // (b) the dump sweep runs AFTER the mcycle/minstret reads, so the sweep's
431	  //     vse8.v insns (and any counter increments) cannot corrupt the drained
432	  //     counters. minstret(0xB02) is the last counter read before the sweep.
433	  std::optional<std::size_t> minstret_read_idx;
434	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
435	    const auto& op = bus.ops[i];
436	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
437	    const auto regno   = static_cast<uint16_t>(op.value & 0xFFFFu);
438	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
439	    if (is_read && regno == hybrid::regno_csr(0xB02)) minstret_read_idx = i;
440	  }
441	  REQUIRE(minstret_read_idx.has_value());
442	  CHECK(*minstret_read_idx < *first_vse_idx);
443	}
