449	
450	// Index of the last DMCONTROL write in the op log.
451	auto last_dmcontrol_write(const std::vector<DmiOp>& ops)
452	  -> std::optional<std::size_t>
453	{
454	  std::optional<std::size_t> at;
455	  for (std::size_t i = 0; i < ops.size(); ++i)
456	    if (ops[i].kind == DmiOp::Kind::Write && ops[i].reg == RD::kDmcontrol)
457	      at = i;
458	  return at;
459	}
460	
461	// Index of the last Program Buffer slot-0 write carrying `insn`.
462	auto last_progbuf_insn(const std::vector<DmiOp>& ops, uint32_t insn)
463	  -> std::optional<std::size_t>
464	{
465	  std::optional<std::size_t> at;
466	  for (std::size_t i = 0; i < ops.size(); ++i)
467	    if (ops[i].kind == DmiOp::Kind::Write && ops[i].reg == hybrid::kProgbuf0
468	        && ops[i].value == insn)
469	      at = i;
470	  return at;
471	}
472	
473	// All abstract-command WRITES to `regno`: (op index of COMMAND, 64-bit value
474	// assembled from the DATA0/DATA1 writes immediately preceding it).
475	auto abstract_writes_to(const std::vector<DmiOp>& ops, uint16_t regno)
476	  -> std::vector<std::pair<std::size_t, uint64_t>>
477	{
478	  std::vector<std::pair<std::size_t, uint64_t>> hits;
479	  uint32_t data0 = 0;
480	  uint32_t data1 = 0;
481	  for (std::size_t i = 0; i < ops.size(); ++i) {
482	    const auto& op = ops[i];
483	    if (op.kind != DmiOp::Kind::Write) continue;
484	    if (op.reg == RD::kData0) { data0 = op.value; continue; }
485	    if (op.reg == RD::kData1) { data1 = op.value; continue; }
486	    if (op.reg != RD::kCommand) continue;
487	    const auto target  = static_cast<uint16_t>(op.value & 0xFFFFu);
488	    const bool is_write = ((op.value >> 16) & 1u) != 0u;
489	    if (is_write && target == regno)
490	      hits.emplace_back(i, (static_cast<uint64_t>(data1) << 32) | data0);
491	  }
492	  return hits;
493	}
