498	          "write, followed by the resumeack poll")
499	{
500	  RecordingBus bus;
501	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
502	
503	  hybrid_state_v1 input{};
504	  input.magic   = HYBRID_STATE_MAGIC;
505	  input.version = HYBRID_STATE_VERSION;
506	  input.flags   = HYBRID_FLAG_RV64;
507	  input.priv    = 3;
508	
509	  hybrid::StateDrain drain(bus);
510	  (void) drain.drain_checkpoint(input);
511	
512	  const auto at = last_dmcontrol_write(bus.ops);
513	  REQUIRE(at.has_value());
514	  CHECK((bus.ops[*at].value & RD::kDmcontrolResumereq) != 0u);
515	  CHECK((bus.ops[*at].value & RD::kDmcontrolHaltreq) == 0u);
516	
517	  // The resumeack poll reads dmstatus after the resume request.
518	  bool polled = false;
519	  for (std::size_t i = *at + 1; i < bus.ops.size(); ++i)
520	    if (bus.ops[i].kind == DmiOp::Kind::Read && bus.ops[i].reg == RD::kDmstatus)
521	      polled = true;
522	  CHECK(polled);
523	}
524	
525	TEST_CASE("drain_checkpoint returns the same architectural state as "
526	          "drain_with_passthrough")
527	{
528	  hybrid_state_v1 input{};
529	  input.magic   = HYBRID_STATE_MAGIC;
530	  input.version = HYBRID_STATE_VERSION;
531	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP | HYBRID_FLAG_V;
532	  input.priv    = 3;
533	  input.mstatus = 0x1800ULL;
534	  input.vlenb   = 64;
535	
536	  const auto program = [](RecordingBus& bus) {
537	    bus.dmstatus_value = kDmstatusHaltedAndAcked;
538	    bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80001234ULL;
539	    for (uint16_t i = 0; i < 32; ++i) {
540	      bus.regfile[hybrid::regno_gpr(i)] = 0x10000000ULL + i;
541	      bus.regfile[hybrid::regno_fpr(i)] = 0xf000000000000000ULL + i;
542	    }
543	    bus.regfile[hybrid::regno_csr(RD::kCsrVl)]    = 16;
544	    bus.regfile[hybrid::regno_csr(RD::kCsrVtype)] = 0xC1ULL;
545	  };
546	
547	  RecordingBus bus_a;
548	  RecordingBus bus_b;
549	  program(bus_a);
550	  program(bus_b);
551	
552	  hybrid::StateDrain plain(bus_a);
553	  hybrid::StateDrain ckpt(bus_b);
554	  const auto want = plain.drain_with_passthrough(input);
555	  const auto got  = ckpt.drain_checkpoint(input);
556	
557	  CHECK(std::memcmp(&want, &got, sizeof(want)) == 0);
558	}
559	
560	TEST_CASE("drain_checkpoint with HYBRID_FLAG_V undoes the dump sweep's clobbers "
561	          "(vtype/vl via vsetvl, vstart, x5/x6/x7) before resuming")
562	{
563	  RecordingBus bus;
564	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
565	  bus.regfile[hybrid::regno_csr(RD::kCsrVl)]     = 16;
566	  bus.regfile[hybrid::regno_csr(RD::kCsrVtype)]  = 0xC1ULL;
567	  bus.regfile[hybrid::regno_csr(RD::kCsrVstart)] = 7;
568	  bus.regfile[hybrid::regno_gpr(5)] = 0x55;
569	  bus.regfile[hybrid::regno_gpr(6)] = 0x66;
570	  bus.regfile[hybrid::regno_gpr(7)] = 0x77;
571	
572	  hybrid_state_v1 input{};
573	  input.magic   = HYBRID_STATE_MAGIC;
574	  input.version = HYBRID_STATE_VERSION;
575	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
576	  input.priv    = 3;
577	  input.vlenb   = 64;
578	
579	  hybrid::StateDrain drain(bus);
580	  (void) drain.drain_checkpoint(input);
581	
582	  // (a) the undo vsetvl runs AFTER the dump sweep's last vse8.v (v31).
583	  const auto last_vse =
584	    last_progbuf_insn(bus.ops, hybrid::encode_vse8_v(31, 7));
585	  const auto undo_vsetvl =
586	    last_progbuf_insn(bus.ops, hybrid::encode_vsetvl(0, 5, 6));
587	  REQUIRE(last_vse.has_value());
588	  REQUIRE(undo_vsetvl.has_value());
589	  CHECK(*last_vse < *undo_vsetvl);
590	
591	  // (b) the undo vsetvl is staged with the DRAINED vl/vtype (not the sweep's
592	  //     e8/m1 constants): the last x5/x6 writes before it carry 16 / 0xC1.
593	  const auto x5_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(5));
594	  const auto x6_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(6));
595	  std::optional<uint64_t> staged_vl;
596	  std::optional<uint64_t> staged_vtype;
597	  for (const auto& [i, v] : x5_writes)
598	    if (i < *undo_vsetvl) staged_vl = v;
599	  for (const auto& [i, v] : x6_writes)
600	    if (i < *undo_vsetvl) staged_vtype = v;
601	  REQUIRE(staged_vl.has_value());
602	  REQUIRE(staged_vtype.has_value());
603	  CHECK(*staged_vl == 16u);
604	  CHECK(*staged_vtype == 0xC1ULL);
605	
606	  // (c) vstart is restored via PB csrrw after the vsetvl (which zeroes it).
607	  const auto vstart_csrrw =
608	    last_progbuf_insn(bus.ops, hybrid::encode_csrrw(0, RD::kCsrVstart, 7));
609	  REQUIRE(vstart_csrrw.has_value());
610	  CHECK(*undo_vsetvl < *vstart_csrrw);
611	  const auto x7_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(7));
612	  std::optional<uint64_t> staged_vstart;
613	  for (const auto& [i, v] : x7_writes)
614	    if (i > *undo_vsetvl && i < *vstart_csrrw) staged_vstart = v;
615	  REQUIRE(staged_vstart.has_value());
616	  CHECK(*staged_vstart == 7u);
617	
618	  // (d) the scratch GPRs are restored LAST with the drained values.
619	  REQUIRE(!x5_writes.empty());
620	  REQUIRE(!x6_writes.empty());
621	  REQUIRE(!x7_writes.empty());
622	  CHECK(x5_writes.back().second == 0x55u);
623	  CHECK(x6_writes.back().second == 0x66u);
624	  CHECK(x7_writes.back().second == 0x77u);
625	  CHECK(x5_writes.back().first > *vstart_csrrw);
626	
627	  // (e) resume comes after everything above.
628	  const auto resume = last_dmcontrol_write(bus.ops);
629	  REQUIRE(resume.has_value());
630	  CHECK((bus.ops[*resume].value & RD::kDmcontrolResumereq) != 0u);
631	  CHECK(*resume > x7_writes.back().first);
632	}
633	
634	TEST_CASE("drain_checkpoint without HYBRID_FLAG_V issues no Program Buffer ops "
635	          "and still resumes")
636	{
637	  RecordingBus bus;
638	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
639	
640	  hybrid_state_v1 input{};
641	  input.magic   = HYBRID_STATE_MAGIC;
