658	}
659	
660	TEST_CASE("L6: drain reads the hart privilege from dcsr.prv")
661	{
662	  RecordingBus bus;
663	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
664	  // dcsr: xdebugver=4, cause=3 (haltreq), prv=1 (S-mode at halt).
665	  bus.regfile[hybrid::regno_csr(RD::kCsrDcsr)] = 0x400000C1ULL;
666	
667	  hybrid::StateDrain drain(bus);
668	  const auto state = drain.drain();
669	
670	  CHECK(state.priv == 1u);
671	}
672	
673	TEST_CASE("L6: drain_with_passthrough reports the freshly drained privilege, "
674	          "not the QEMU1 snapshot's")
675	{
676	  RecordingBus bus;
677	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
678	  bus.regfile[hybrid::regno_csr(RD::kCsrDcsr)] = 0x40000000ULL;  // prv=0 (U)
679	
680	  hybrid_state_v1 input{};
681	  input.magic   = HYBRID_STATE_MAGIC;
682	  input.version = HYBRID_STATE_VERSION;
683	  input.flags   = HYBRID_FLAG_RV64;
684	  input.priv    = 3;  // stale: QEMU1 drained M before the ROI dropped to U
