TEST_CASE("drain_full reads the trap CSR block from the DM (no passthrough)")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64;  // misa: no F/D/V
  bus.regfile[hybrid::regno_csr(RD::kCsrMstatus)]  = 0x1888ULL;
  bus.regfile[hybrid::regno_csr(0x341)] = 0x111ULL;  // mepc
  bus.regfile[hybrid::regno_csr(0x342)] = 0x2ULL;    // mcause
  bus.regfile[hybrid::regno_csr(0x343)] = 0x333ULL;  // mtval
  bus.regfile[hybrid::regno_csr(0x340)] = 0x444ULL;  // mscratch
  bus.regfile[hybrid::regno_csr(RD::kCsrMtvec)] = 0x555ULL;
  bus.regfile[hybrid::regno_csr(0x302)] = 0x666ULL;  // medeleg
  bus.regfile[hybrid::regno_csr(0x303)] = 0x777ULL;  // mideleg
  bus.regfile[hybrid::regno_csr(0x344)] = 0x888ULL;  // mip
  bus.regfile[hybrid::regno_csr(0x304)] = 0x999ULL;  // mie
  bus.regfile[hybrid::regno_csr(0x180)] = 0xAAAULL;  // satp

