  CHECK(state.mstatus  == 0x1888ULL);
  CHECK(state.mepc     == 0x111ULL);
  CHECK(state.mcause   == 0x2ULL);
  CHECK(state.mtval    == 0x333ULL);
  CHECK(state.mscratch == 0x444ULL);
  CHECK(state.mtvec    == 0x555ULL);
  CHECK(state.medeleg  == 0x666ULL);
  CHECK(state.mideleg  == 0x777ULL);
  CHECK(state.mip      == 0x888ULL);
  CHECK(state.mie      == 0x999ULL);
  CHECK(state.satp     == 0xAAAULL);
}

