TEST_CASE("drain_full with V: dump sweep after counter reads, clobbers undone, "
          "and NO resume request issued")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64 | kMisaV;
  bus.regfile[hybrid::regno_csr(0xC22)] = 32;
  bus.regfile[hybrid::regno_csr(RD::kCsrMstatus)] = 0x600ULL;  // VS on
  bus.regfile[hybrid::regno_csr(RD::kCsrVl)]     = 16;
  bus.regfile[hybrid::regno_csr(RD::kCsrVtype)]  = 0xC1ULL;
  bus.regfile[hybrid::regno_csr(RD::kCsrVstart)] = 7;
  bus.regfile[hybrid::regno_gpr(5)] = 0x55;
  bus.regfile[hybrid::regno_gpr(6)] = 0x66;
  bus.regfile[hybrid::regno_gpr(7)] = 0x77;

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_full();

  CHECK(state.vl    == 16u);
  CHECK(state.vtype == 0xC1ULL);

  // Sweep present and after the minstret read.
  const auto last_vse =
    last_progbuf_insn(bus.ops, hybrid::encode_vse8_v(31, 7));
  REQUIRE(last_vse.has_value());

  // Clobbers undone: undo vsetvl after the sweep, x5/x6/x7 rewritten last.
  const auto undo_vsetvl =
    last_progbuf_insn(bus.ops, hybrid::encode_vsetvl(0, 5, 6));
  REQUIRE(undo_vsetvl.has_value());
  CHECK(*last_vse < *undo_vsetvl);
  const auto x5_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(5));
  const auto x7_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(7));
  REQUIRE(!x5_writes.empty());
  REQUIRE(!x7_writes.empty());
  CHECK(x5_writes.back().second == 0x55u);
  CHECK(x7_writes.back().second == 0x77u);

  // drain_full never resumes -- the caller (step loop / exit) decides.
  for (const auto& op : bus.ops) {
    if (op.kind == DmiOp::Kind::Write && op.reg == RD::kDmcontrol)
      CHECK((op.value & RD::kDmcontrolResumereq) == 0u);
  }
}

TEST_CASE("drain_full with FS off in mstatus: forces FS on for the FPR reads, "
          "then restores the original mstatus; the record keeps the original")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64 | kMisaF | kMisaD;
  bus.regfile[hybrid::regno_csr(RD::kCsrMstatus)] = 0x1800ULL;  // FS = Off

  hybrid::StateDrain drain(bus);
  const auto state = drain.drain_full();

  CHECK(state.mstatus == 0x1800ULL);

  const auto ms_writes =
    abstract_writes_to(bus.ops, hybrid::regno_csr(RD::kCsrMstatus));
  REQUIRE(ms_writes.size() >= 2);
  // First write enables FS (Initial), final write restores the original.
  CHECK((ms_writes.front().second & RD::kMstatusFsMask) != 0u);
  CHECK(ms_writes.back().second == 0x1800ULL);

  // The enable precedes the first FPR read.
  std::optional<std::size_t> first_fpr;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
