    if (regno >= hybrid::regno_fpr(0) && regno <= hybrid::regno_fpr(31)) {
      first_fpr = i;
      break;
    }
  }
  REQUIRE(first_fpr.has_value());
  CHECK(ms_writes.front().first < *first_fpr);
}

